import type { BrandCanvas, BrandExpression } from './BrandMark.types';

/**
 * Where each of the four marks lives.
 *
 * All four are generated by `design-kit/seti.live/marks/generate.py` from the
 * supplied neutral artwork, on ONE 384px square canvas with one crop and one
 * scale, so swapping expression or canvas never shifts the mark by a pixel.
 * They are copies: the kit is where marks are authored, `web/public` is what the
 * app serves.
 */
export const BRAND_MARK_SRC: Record<BrandExpression, Record<BrandCanvas, string>> = {
  neutral: {
    light: '/seti-mark-neutral.png',
    dark: '/seti-mark-neutral-dark.png',
  },
  friendly: {
    light: '/seti-mark-friendly.png',
    dark: '/seti-mark-friendly-dark.png',
  },
};

/** The intrinsic size every mark is exported at. Square, so a height sizes it. */
export const BRAND_MARK_SIZE = 384;
